-- DigiNanba Project Management: modular operational and commercial foundations.
-- Additive, organization-scoped tables. No live billing or payment activation.
BEGIN;
CREATE TABLE IF NOT EXISTS pm_resource_types (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organization_accounts(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, unit text, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), UNIQUE(organization_id,id), UNIQUE(organization_id,code));
CREATE TABLE IF NOT EXISTS pm_resources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organization_accounts(id) ON DELETE CASCADE, resource_type_id uuid, resource_code text, name text NOT NULL, description text NOT NULL DEFAULT '', resource_class text NOT NULL DEFAULT 'equipment', unit text, capacity numeric(18,4), cost_rate numeric(18,4), currency_code char(3) NOT NULL DEFAULT 'INR', status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','allocated','maintenance','inactive')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), FOREIGN KEY(organization_id,resource_type_id) REFERENCES pm_resource_types(organization_id,id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS pm_resource_allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, project_id uuid NOT NULL, resource_id uuid NOT NULL, start_at timestamptz, finish_at timestamptz, planned_quantity numeric(18,4), actual_quantity numeric(18,4), status text NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','allocated','released','cancelled')), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,project_id) REFERENCES pm_projects(organization_id,id) ON DELETE CASCADE, FOREIGN KEY(organization_id,resource_id) REFERENCES pm_resources(organization_id,id) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS pm_resource_allocations_project_idx ON pm_resource_allocations(organization_id,project_id,start_at);
CREATE TABLE IF NOT EXISTS pm_material_catalog (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organization_accounts(id) ON DELETE CASCADE, item_code text, name text NOT NULL, specification text NOT NULL DEFAULT '', unit text NOT NULL, default_rate numeric(18,4), currency_code char(3) NOT NULL DEFAULT 'INR', tax_code text, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,item_code));
CREATE TABLE IF NOT EXISTS pm_material_indents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, project_id uuid NOT NULL, indent_number text NOT NULL, requested_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, required_by date, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','rejected','partially_ordered','ordered','closed','cancelled')), purpose text NOT NULL DEFAULT '', approved_by uuid REFERENCES users(id) ON DELETE RESTRICT, approved_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,indent_number), FOREIGN KEY(organization_id,project_id) REFERENCES pm_projects(organization_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS pm_material_indent_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, indent_id uuid NOT NULL, material_id uuid, description text NOT NULL, specification text NOT NULL DEFAULT '', unit text NOT NULL, target_quantity numeric(18,4) NOT NULL CHECK(target_quantity>0), approved_quantity numeric(18,4), received_quantity numeric(18,4) NOT NULL DEFAULT 0, estimated_rate numeric(18,4), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,indent_id) REFERENCES pm_material_indents(organization_id,id) ON DELETE CASCADE, FOREIGN KEY(organization_id,material_id) REFERENCES pm_material_catalog(organization_id,id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS pm_suppliers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organization_accounts(id) ON DELETE CASCADE, supplier_code text, legal_name text NOT NULL, contact_name text, email text, phone text, tax_registration_number text, address jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive','blocked')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,supplier_code));
CREATE TABLE IF NOT EXISTS pm_purchase_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, project_id uuid NOT NULL, supplier_id uuid NOT NULL, po_number text NOT NULL, issue_date date NOT NULL DEFAULT CURRENT_DATE, expected_delivery_date date, currency_code char(3) NOT NULL DEFAULT 'INR', subtotal numeric(18,2) NOT NULL DEFAULT 0, tax_total numeric(18,2) NOT NULL DEFAULT 0, total_amount numeric(18,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','sent','partially_received','received','closed','cancelled')), terms jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, approved_by uuid REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,po_number), FOREIGN KEY(organization_id,project_id) REFERENCES pm_projects(organization_id,id) ON DELETE CASCADE, FOREIGN KEY(organization_id,supplier_id) REFERENCES pm_suppliers(organization_id,id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS pm_quality_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organization_accounts(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, standard_reference text, revision text NOT NULL DEFAULT '1', checklist jsonb NOT NULL DEFAULT '[]'::jsonb, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','superseded','archived')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,code,revision));
CREATE TABLE IF NOT EXISTS pm_quality_inspections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, project_id uuid NOT NULL, template_id uuid, inspection_number text NOT NULL, inspection_type text NOT NULL DEFAULT 'inspection', inspected_at timestamptz, inspector_membership_id uuid, result text NOT NULL DEFAULT 'pending' CHECK(result IN ('pending','pass','fail','conditional','rework')), findings jsonb NOT NULL DEFAULT '[]'::jsonb, corrective_action text NOT NULL DEFAULT '', due_date date, closed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,inspection_number), FOREIGN KEY(organization_id,project_id) REFERENCES pm_projects(organization_id,id) ON DELETE CASCADE, FOREIGN KEY(organization_id,template_id) REFERENCES pm_quality_templates(organization_id,id) ON DELETE RESTRICT, FOREIGN KEY(organization_id,inspector_membership_id) REFERENCES pm_memberships(organization_id,id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS pm_financial_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, project_id uuid, entry_number text NOT NULL, entry_type text NOT NULL CHECK(entry_type IN ('budget','commitment','income','expense','receipt','payment','journal')), entry_date date NOT NULL DEFAULT CURRENT_DATE, description text NOT NULL, account_code text, party_type text, party_id uuid, currency_code char(3) NOT NULL DEFAULT 'INR', amount numeric(18,2) NOT NULL, tax_amount numeric(18,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','approved','posted','void')), source_type text, source_id uuid, created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, approved_by uuid REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,entry_number), FOREIGN KEY(organization_id) REFERENCES organization_accounts(id) ON DELETE CASCADE, FOREIGN KEY(organization_id,project_id) REFERENCES pm_projects(organization_id,id) ON DELETE RESTRICT);
CREATE INDEX IF NOT EXISTS pm_financial_project_date_idx ON pm_financial_entries(organization_id,project_id,entry_date DESC);
CREATE TABLE IF NOT EXISTS pm_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organization_accounts(id) ON DELETE CASCADE, project_id uuid, document_number text, title text NOT NULL, document_type text NOT NULL DEFAULT 'general', revision text NOT NULL DEFAULT 'A', storage_key text NOT NULL, mime_type text, file_size_bytes bigint, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','in_review','approved','superseded','archived')), uploaded_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, approved_by uuid REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), FOREIGN KEY(organization_id,project_id) REFERENCES pm_projects(organization_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS pm_clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organization_accounts(id) ON DELETE CASCADE, client_code text, legal_name text NOT NULL, contact_name text, email text, phone text, address jsonb NOT NULL DEFAULT '{}'::jsonb, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,client_code));
CREATE TABLE IF NOT EXISTS pm_communication_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organization_accounts(id) ON DELETE CASCADE, project_id uuid, subject text NOT NULL, thread_type text NOT NULL DEFAULT 'internal' CHECK(thread_type IN ('internal','client','supplier','department')), visibility text NOT NULL DEFAULT 'participants' CHECK(visibility IN ('organization','project','participants','external_portal')), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed','archived')), created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), FOREIGN KEY(organization_id,project_id) REFERENCES pm_projects(organization_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS pm_communication_participants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, thread_id uuid NOT NULL, user_id uuid REFERENCES users(id) ON DELETE CASCADE, external_email text, participant_role text NOT NULL DEFAULT 'member', last_read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK(user_id IS NOT NULL OR external_email IS NOT NULL), FOREIGN KEY(organization_id,thread_id) REFERENCES pm_communication_threads(organization_id,id) ON DELETE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS pm_communication_participant_user_idx ON pm_communication_participants(thread_id,user_id) WHERE user_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS pm_communication_participant_email_idx ON pm_communication_participants(thread_id,lower(external_email)) WHERE external_email IS NOT NULL;
CREATE TABLE IF NOT EXISTS pm_communication_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, thread_id uuid NOT NULL, sender_user_id uuid REFERENCES users(id) ON DELETE RESTRICT, body text NOT NULL, attachments jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(organization_id,thread_id) REFERENCES pm_communication_threads(organization_id,id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS pm_communication_messages_thread_idx ON pm_communication_messages(organization_id,thread_id,created_at);
CREATE TABLE IF NOT EXISTS pm_module_catalog (module_code text PRIMARY KEY, name text NOT NULL, description text NOT NULL DEFAULT '', billing_mode text NOT NULL DEFAULT 'included' CHECK(billing_mode IN ('included','optional_addon','usage_metered')), is_active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS pm_organization_modules (organization_id uuid NOT NULL REFERENCES organization_accounts(id) ON DELETE CASCADE, module_code text NOT NULL REFERENCES pm_module_catalog(module_code) ON DELETE RESTRICT, enabled boolean NOT NULL DEFAULT false, enabled_at timestamptz, configuration jsonb NOT NULL DEFAULT '{}'::jsonb, PRIMARY KEY(organization_id,module_code));
CREATE TABLE IF NOT EXISTS pm_usage_events (id bigserial PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organization_accounts(id) ON DELETE CASCADE, meter_code text NOT NULL, quantity numeric(20,4) NOT NULL CHECK(quantity>=0), unit text NOT NULL, idempotency_key text NOT NULL, source_type text, source_id uuid, occurred_at timestamptz NOT NULL DEFAULT now(), recorded_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,idempotency_key));
CREATE INDEX IF NOT EXISTS pm_usage_events_org_meter_time_idx ON pm_usage_events(organization_id,meter_code,occurred_at DESC);
INSERT INTO pm_module_catalog(module_code,name,description,billing_mode) VALUES
('projects','Projects & tasks','Project portfolio, work breakdown and task execution','included'),
('performance','Performance ledger','Targets, actuals, variance, status and corrective actions','included'),
('people','People & workforce','Organization structure, roles, manpower and assignments','optional_addon'),
('resources','Resources & equipment','Resource register, allocation and utilization','optional_addon'),
('procurement','Materials & procurement','Material indents, suppliers and purchase orders','optional_addon'),
('quality','Quality & standards','Inspection plans, checklists, nonconformities and corrective actions','optional_addon'),
('finance','Project finance','Budgets, commitments, income, expenses and approvals','optional_addon'),
('documents','Documents & approvals','Controlled files, revisions and approval workflows','optional_addon'),
('crm_communications','CRM & communications','Client/supplier records, project threads and portals','optional_addon'),
('analytics','Analytics & reports','Portfolio, operational and financial dashboards','usage_metered')
ON CONFLICT(module_code) DO NOTHING;
COMMIT;
